), serie_alvo AS (
    SELECT s.id FROM series s JOIN editoras e ON e.id=s.editora_id
    WHERE hqhub_normalizar_titulo_serie(s.titulo)=hqhub_normalizar_titulo_serie('Coleção Carl Barks Definitiva')
      AND lower(trim(e.nome)) LIKE 'panini%' AND coalesce(s.volume,1)=1
    ORDER BY s.id LIMIT 1
)
INSERT INTO edicoes (numero,titulo,url_capa,fonte_externa,id_externo,url_origem,serie_id,data_criacao,data_atualizacao)
SELECT r.numero,r.titulo,r.url_capa,'PLANETA_GIBI','PLANETA-GIBI-CARL-BARKS-'||lpad(r.numero,2,'0'),
       'https://www.planetagibiblog.com.br/2017/01/guia-planeta-gibi-colecao-carl-barks.html#COL',
       s.id,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP
FROM referencias r CROSS JOIN serie_alvo s
ON CONFLICT (serie_id, hqhub_normalizar_identidade(numero::text)) DO UPDATE
SET titulo=EXCLUDED.titulo,url_capa=EXCLUDED.url_capa,fonte_externa=EXCLUDED.fonte_externa,
    id_externo=EXCLUDED.id_externo,url_origem=EXCLUDED.url_origem,data_atualizacao=CURRENT_TIMESTAMP;
